def _clamp01(value: float) -> float:
    return 0.0 if value < 0.0 else 1.0 if value > 1.0 else value


def _as_box(box: Sequence[Any]) -> tuple[int, int, int, int] | None:
    if not isinstance(box, Sequence) or isinstance(box, (str, bytes)):
        return None
    if len(box) != 4:
        return None
    try:
        x0, y0, x1, y1 = (int(round(float(value))) for value in box)
    except (TypeError, ValueError):
        return None
    return (x0, y0, x1, y1) if x1 > x0 and y1 > y0 else None


def _cell_averages(image: Image.Image, box: tuple[int, int, int, int]) -> list[tuple[int, int, int]]:
    """Return the mean colour of each of the nine cells of *box*.

    The whole box is reduced in one resampling pass, which keeps the detector's
    inner loop cheap enough to sweep a wide search window.
    """
    x0, y0, x1, y1 = box
    reduced = image.crop((x0, y0, x1, y1)).resize(MARKER_GRID, Image.BOX)
    return [
        (int(reduced.getpixel((column, row))[0]),
         int(reduced.getpixel((column, row))[1]),
         int(reduced.getpixel((column, row))[2]))
        for row in range(MARKER_GRID[1])
        for column in range(MARKER_GRID[0])
    ]


def _ramp_quality(cells: Sequence[tuple[int, int, int]]) -> tuple[float, float]:
    """Score how well *cells* reproduce the marker's three driven ramps.

    Returns the separation between the driven channel and the two held ones,
    and the fraction of columns whose driven channel rises across the rows.
    """
    separations: list[float] = []
    rising = 0
    for column, channel in enumerate(COLUMN_CHANNELS):
        held = [index for index in (0, 1, 2) if index != channel]
        levels = [cells[row * MARKER_GRID[0] + column][channel] for row in range(MARKER_GRID[1])]
        for row in range(MARKER_GRID[1]):
            value = cells[row * MARKER_GRID[0] + column]
            others = max(value[index] for index in held)
            separations.append(_clamp01((value[channel] - others) / SEPARATION_SCALE))
        if levels[0] < levels[1] < levels[2]:
            rising += 1
    return sum(separations) / len(separations), rising / len(COLUMN_CHANNELS)


def _candidate_score(image: Image.Image, box: Sequence[Any]) -> float:
    """Score how strongly *box* reads as a 3x3 identity marker.

    The score combines three independent requirements -- channel separation, a
    rising ramp per column, and a dark-to-bright span -- as a geometric mean,
    so a box that fails any one of them cannot score highly by excelling at the
    others, while a clean marker sits near the top of the range regardless of
    which of the three is strongest.
    """
    resolved = _as_box(box)
    if resolved is None:
        return 0.0
    x0, y0, x1, y1 = resolved
    if x1 - x0 < MINIMUM_MARKER_SIDE or y1 - y0 < MINIMUM_MARKER_SIDE:
        return 0.0
    if x0 < 0 or y0 < 0 or x1 > image.width or y1 > image.height:
        return 0.0
    cells = _cell_averages(image, resolved)
    separation, rising = _ramp_quality(cells)
    span = 0.0
    for column, channel in enumerate(COLUMN_CHANNELS):
        dark = cells[column][channel]
        bright = cells[(MARKER_GRID[1] - 1) * MARKER_GRID[0] + column][channel]
        span += _clamp01((bright - dark) / RAMP_SPAN_SCALE)
    span /= len(COLUMN_CHANNELS)
    factors = (max(separation, 1e-9), max(rising, 1e-9), max(span, 1e-9))
    return _clamp01((factors[0] * factors[1] * factors[2]) ** (1.0 / 3.0))


def _search_window(width: int, height: int) -> tuple[int, int, int, int]:
    """Return the region of the frame the marker search may look in."""
    left, top, right, bottom = SEARCH_WINDOW
    window = (
        max(0, int(width * left)),
        max(0, int(height * top)),
        min(width, int(width * right)),
        min(height, int(height * bottom)),
    )
    if window[2] - window[0] < MINIMUM_MARKER_SIDE or window[3] - window[1] < MINIMUM_MARKER_SIDE:
        return (0, 0, width, height)
    return window


def _best_in(
    image: Image.Image,
    window: tuple[int, int, int, int],
    sides: Sequence[int],
    step: int,
    current: tuple[float, tuple[int, int, int, int] | None],
) -> tuple[float, tuple[int, int, int, int] | None]:
    """Sweep *sides* across *window* and keep the strongest scoring box."""
    width, height = image.size
    best_score, best_box = current
    for side in sides:
        if side < MINIMUM_MARKER_SIDE:
            continue
        for y0 in range(window[1], max(window[1] + 1, window[3] + 1), step):
            for x0 in range(window[0], max(window[0] + 1, window[2] + 1), step):
                box = (x0, y0, x0 + side, y0 + side)
                if box[2] > width or box[3] > height:
                    continue
                score = _candidate_score(image, box)
                if score > best_score:
                    best_score, best_box = score, box
    return best_score, best_box


def _search_box(image: Image.Image) -> tuple[int, int, int, int] | None:
    """Return the best-scoring marker box, or ``None`` when none is plausible."""
    width, height = image.size
    window = _search_window(width, height)
    shorter = min(width, height)
    sides = sorted({max(MINIMUM_MARKER_SIDE, int(shorter * fraction)) for fraction in SEARCH_SIDES})
    coarse_step = max(4, min(window[2] - window[0], window[3] - window[1]) // 12)

    best_score, best_box = _best_in(image, window, sides, coarse_step, (0.0, None))
    if best_box is None:
        return None

    fine_step = max(2, coarse_step // 4)
    fine_window = (
        max(window[0], best_box[0] - coarse_step),
        max(window[1], best_box[1] - coarse_step),
        min(window[2], best_box[2] - coarse_step),
        min(window[3], best_box[3] - coarse_step),
    )
    base_side = best_box[2] - best_box[0]
    fine_sides = sorted(
        {
            max(MINIMUM_MARKER_SIDE, base_side + delta)
            for delta in range(-coarse_step, coarse_step + 1, fine_step)
        }
    )
    _, best_box = _best_in(image, fine_window, fine_sides, fine_step, (best_score, best_box))
    return best_box


def _median_cell_colours(image: Image.Image, box: tuple[int, int, int, int]) -> list[dict[str, Any]]:
    """Return the per-channel median colour of each of the nine marker cells."""
    x0, y0, x1, y1 = box
    step_x = (x1 - x0) / MARKER_GRID[0]
    step_y = (y1 - y0) / MARKER_GRID[1]
    cells: list[dict[str, Any]] = []
    for row in range(MARKER_GRID[1]):
        for column in range(MARKER_GRID[0]):
            cell_box = (
                int(round(x0 + column * step_x)),
                int(round(y0 + row * step_y)),
                int(round(x0 + (column + 1) * step_x)),
                int(round(y0 + (row + 1) * step_y)),
            )
            region = image.crop(cell_box)
            width, height = region.size
            channels = [
                region.getpixel((x, y))
                for y in range(height)
                for x in range(width)
            ]
            medians = [
                int(median(pixel[index] for pixel in channels)) if channels else 0
                for index in range(3)
            ]
            cells.append(
                {
                    "row": row,
                    "column": column,
                    "box": list(cell_box),
                    "pixels": len(channels),
                    "median_rgb": medians,
                }
            )
    return cells


def _identity(cells: Sequence[Mapping[str, Any]]) -> tuple[int | None, float]:
    """Match observed cell medians against the recorded marker identities.

    Two markers can sit within one unit of each other on a single cell, so the
    whole grid is compared at once and the confidence reports how far the
    winner is ahead of the runner-up rather than how close the winner is in
    absolute terms.
    """
    observed = [list(cell.get("median_rgb") or [0, 0, 0])[:3] for cell in cells]
    if len(observed) != MARKER_CELL_COUNT:
        return None, 0.0
    distances: list[tuple[float, int]] = []
    for index, expected in sorted(MARKER_CELL_MEDIANS.items()):
        total = 0.0
        for cell, reference in zip(observed, expected):
            total += sum(abs(int(cell[channel]) - reference[channel]) for channel in range(3))
        distances.append((total / (MARKER_CELL_COUNT * 3), index))
    if not distances:
        return None, 0.0
    distances.sort()
    best_distance, best_index = distances[0]
    runner_up = distances[1][0] if len(distances) > 1 else best_distance + 255.0
    confidence = _clamp01((runner_up - best_distance) / max(1.0, runner_up))
    return best_index, confidence


def extract_marker_signature(image: Image.Image, box: Sequence[Any]) -> dict[str, Any]:
    """Return the readable identity signature of the marker at *box*."""
    resolved = _as_box(box)
    if resolved is None:
        raise ValueError(f"marker box is not a usable rectangle: {box!r}")
    cells = _median_cell_colours(image, resolved)
    marker_index, confidence = _identity(cells)
    return {
        "marker_version": MARKER_VERSION,
        "grid": list(MARKER_GRID),
        "box": list(resolved),
        "side": resolved[2] - resolved[0],
        "rgb_cells": cells,
        "marker_index": marker_index,
        "identity_confidence": round(confidence, 5),
    }


def detect_rgb_marker(image: Image.Image) -> dict[str, Any] | None:
    """Return the identity marker found in *image*, or ``None`` when absent."""
    box = _search_box(image)
    if box is None:
        return None
    score = _candidate_score(image, box)
    if score <= 0.0:
        return None
    signature = extract_marker_signature(image, box)
    return {
        "marker_version": MARKER_VERSION,
        "box": list(box),
        "score": round(score, 5),
        "marker_index": signature["marker_index"],
        "identity_confidence": signature["identity_confidence"],
        "signature": signature,
    }


def _median_of(signature: Mapping[str, Any]) -> list[list[int]]:
    cells = list(signature.get("rgb_cells") or [])
    return [
        [int(value) for value in list(cell.get("median_rgb") or [])[:3]]
        for cell in cells
        if isinstance(cell, Mapping)
    ]


def compare_marker_signatures(
    baseline: Mapping[str, Any], observed: Mapping[str, Any]
) -> dict[str, Any]:
    """Compare two marker signatures cell by cell.

    Reports the mean absolute difference over all 27 channel values together
    with how many channels moved by at least two and at least five levels.  A
    marker that was repainted moves many channels a long way; a marker that
    merely passed through an edit moves its cells together, which is why the
    channel counts and the mean are reported side by side.
    """
    expected = _median_of(baseline)
    actual = _median_of(observed)
    if len(expected) != MARKER_CELL_COUNT or len(actual) != MARKER_CELL_COUNT:
        raise ValueError(
            "marker signatures must each carry nine cells, "
            f"observed {len(expected)} against {len(actual)}"
        )
    deltas = [
        [actual[cell][channel] - expected[cell][channel] for channel in range(3)]
        for cell in range(MARKER_CELL_COUNT)
    ]
    flat = [abs(value) for row in deltas for value in row]
    mean_abs = sum(flat) / len(flat)
    return {
        "cell_deltas": deltas,
        "mean_abs_channel_delta": round(mean_abs, 5),
        "max_abs_channel_delta": max(flat),
        "changed_channel_count_ge_2": sum(1 for value in flat if value >= 2),
        "changed_channel_count_ge_5": sum(1 for value in flat if value >= 5),
        "cell_count": MARKER_CELL_COUNT,
        "channel_count": len(flat),
        "baseline_marker_index": baseline.get("marker_index"),
        "observed_marker_index": observed.get("marker_index"),
        "identity_preserved": baseline.get("marker_index") == observed.get("marker_index"),
    }


def simulator_media_files(simulator_root: str | Path) -> list[Path]:
    """Return every stored photo under a simulator device directory."""
    library = Path(simulator_root)
    for part in SIMULATOR_PHOTO_LIBRARY:
        library = library / part
    if not library.is_dir():
        return []
    return sorted(
        path
        for path in library.rglob("*")
        if path.is_file() and path.suffix.lower() in MEDIA_SUFFIXES
    )


def relative_media_path(path: str | Path, root: str | Path) -> str:
    """Return *path* expressed relative to *root* using forward slashes.

    The stored photo library is compared across machines, so the identity of an
    asset is its path below the device root rather than any absolute location.
    """
    candidate = Path(path)
    base = Path(root)
    try:
        return candidate.relative_to(base).as_posix()
    except ValueError:
        return candidate.as_posix()


def load_marker_image(path: str | Path) -> Image.Image:
    """Open a stored photo and normalise it for marker reading."""
    with Image.open(path) as handle:
        handle.load()
        return handle.convert("RGB")


def iter_marker_rows(
    paths: Iterable[str | Path], root: str | Path
) -> list[dict[str, Any]]:
    """Describe every candidate export under *paths* in a stable order."""
    rows: list[dict[str, Any]] = []
    for path in sorted(paths, key=lambda item: (Path(item).stat().st_mtime_ns, str(item))):
        image = load_marker_image(path)
        detection = detect_rgb_marker(image)
        row: dict[str, Any] = {
            "relative_path": relative_media_path(path, root),
            "dimensions": list(image.size),
            "marker_detected": detection is not None,
            "marker_index": None,
            "detection_score": None,
            "identity_confidence": None,
            "marker_box": None,
            "marker_rgb_medians": [],
        }
        if detection is not None:
            row.update(
                {
                    "marker_index": detection["marker_index"],
                    "detection_score": detection["score"],
                    "identity_confidence": detection["identity_confidence"],
                    "marker_box": detection["box"],
                    "marker_rgb_medians": _median_of(detection["signature"]),
                }
            )
        rows.append(row)
    return rows
